local bit_lrotate = bit32.lrotate
local bit_rrotate = bit32.rrotate

local function rt_shl_i32(lhs, rhs)
	return bit_lshift(lhs, rhs % 32)
end

local function rt_shr_u32(lhs, rhs)
	return bit_rshift(lhs, rhs % 32)
