			["_initialize"] = FUNC_LIST[25],
			["puppy_key"] = FUNC_LIST[79],
			["puppy_mouse"] = FUNC_LIST[80],
			["puppy_wadname"] = FUNC_LIST[81],
			["puppy_start"] = FUNC_LIST[82],
			["puppy_tick"] = FUNC_LIST[83],
		},
		table_list = {
		},
		memory_list = {
			["memory"] = MEMORY_LIST[0],
		},
		global_list = {
		},
	}
end

end
local Doom = (function()
-- Host side for the Doom module: WASI file system in memory, clock, screen
-- and input. Doom.new(opts) -> doom
--   opts.wadName, opts.wadData (string), opts.readFile(name) -> string?,
--   opts.writeFile(name, data), opts.deleteFile(name), opts.clock() -> seconds,
--   opts.log(text)?, opts.yield()? (called now and then during start-up)
--   doom.start()  loads the WAD and runs Doom's start-up (may call opts.yield)
--   doom.advance(ms) moves Doom's clock on; doom.tick() then runs the tics that are due and draws a frame
--   doom.blit(out) writes the screen as RGBA into out (a 320 x 200 x 4 buffer); false before the first frame
--   doom.key(pressed, doomKeyCode), doom.mouse(buttons, dx, dy), doom.title
--   opts.sound (optional): Doom's sound calls, each wrapped in pcall
--     start(lumpName, channel, vol 0-127, sep 0-254), stop(channel), params(channel, vol, sep),
--     musicPlay(songData, looping), musicStop(), musicPause(), musicResume(), musicVolume(0-127)
--   Doom.lumps(wad) -> { NAME = { pos = byte offset, size = n } }, list in directory order
--   Doom.sfxWav(wad, lump) -> a WAV file (string) for a Doom sound lump, its length in seconds; nil if not one
local Doom = {}

local ERRNO = { ok = 0, badf = 8, exist = 20, inval = 28, noent = 44, nosys = 52 }

-- which game a WAD is, from its lump directory (Doom picks rules by file name)
local function identify(data)
    if #data < 12 or (data:sub(1, 4) ~= "IWAD" and data:sub(1, 4) ~= "PWAD") then return nil end
    local count = string.unpack("<i4", data, 5)
    local dir = string.unpack("<i4", data, 9)
    local has = {}
    for i = 0, count - 1 do
        local p = dir + i * 16 + 9
        if p + 7 > #data then break end
        local name = data:sub(p, p + 7):gsub("%z.*", ""):upper()
        has[name] = true
    end
    if has["MAP01"] then
        if has["FREEDOOM"] then return "freedoom2.wad" end
        return "doom2.wad"
    end
    if has["E1M1"] then
        if has["FREEDOOM"] then return "freedoom1.wad" end
        if has["E4M1"] or has["E2M1"] then return "doom.wad" end
        return "doom1.wad"
    end
    return nil
end
Doom.identify = identify

local function lumps(data)
    local byName, list = {}, {}
    if #data < 12 then return byName, list end
    local count = string.unpack("<i4", data, 5)
    local dir = string.unpack("<i4", data, 9)
    for i = 0, count - 1 do
        local p = dir + i * 16 + 1
        if p + 15 > #data then break end
        local pos, size = string.unpack("<i4i4", data, p)
        local name = data:sub(p + 8, p + 15):gsub("%z.*", ""):upper()
        if pos >= 0 and size >= 0 and pos + size <= #data then
            local l = { name = name, pos = pos, size = size }
            list[#list + 1] = l
            byName[name] = l -- the last one wins, like Doom
        end
    end
    return byName, list
end
Doom.lumps = lumps

-- Doom sound lumps: u16 format 3, u16 rate, u32 sample count (16 padding bytes at each end
-- included), 8-bit unsigned samples. WAV stores 8-bit samples unsigned too, so they copy as they are.
function Doom.sfxWav(data, l)
    if not l or l.size < 8 + 32 then return nil end
    local fmt, rate, count = string.unpack("<I2I2I4", data, l.pos + 1)
    if fmt ~= 3 or rate < 4000 or count < 32 or count > l.size - 8 then return nil end
    local n = count - 32
    local pcm = data:sub(l.pos + 8 + 16 + 1, l.pos + 8 + 16 + n)
    local header = "RIFF" .. string.pack("<I4", 36 + n) .. "WAVEfmt " .. string.pack("<I4I2I2I4I4I2I2", 16, 1, 1, rate, rate, 1, 8)
        .. "data" .. string.pack("<I4", n)
    return header .. pcm, n / rate
end

function Doom.new(makeWasm, opts)
    local files = {}   -- name -> { buf = buffer, size = n }
    local fds = {}     -- fd -> { name, pos, file, dirty }
    local nextFd = 4
    local mem          -- memory record ({ data = buffer }); data is replaced when memory grows
    local screenPtr, screenW, screenH = nil, 320, 200
    local pal = table.create(256, 4278190080) -- palette index + 1 -> RGBA as a little-endian u32
    local gameMs = 0       -- Doom's clock: advanced by doom.advance (one tic = 1000 / 35 ms)
    local starting = false
    local lastYield = opts.clock()
    local logLines = {}

    local function data() return mem.data end
    local function readStr(ptr, len) return buffer.readstring(mem.data, ptr, len) end
    local function u32(ptr) return buffer.readu32(mem.data, ptr) end
    local function setU32(ptr, v) buffer.writeu32(mem.data, ptr, v) end

    -- 64-bit arguments arrive as the module's Vector3 form (22 + 22 + 20 bits)
    local function i64(v)
        local x, y, z = v.X, v.Y, v.Z
        local lo = x + (z % 1024) * 4194304
        local hi = y + math.floor(z / 1024) * 4194304
        if hi >= 2147483648 then return lo + (hi - 4294967296) * 4294967296 end
        return lo + hi * 4294967296
    end

    local function maybeYield()
        if starting and opts.yield then
            local now = opts.clock()
            if now - lastYield > 0.04 then lastYield = now; opts.yield(); lastYield = opts.clock() end
        end
    end

    local function normal(path)
        path = path:gsub("\\", "/"):gsub("^%./", ""):gsub("^/+", "")
        return path:lower()
    end

    local function fileFromString(s)
        return { buf = buffer.fromstring(s), size = #s }
    end

    local function getFile(name)
        local f = files[name]
        if f then return f end
        local s = opts.readFile and opts.readFile(name)
        if s then
            f = fileFromString(s)
            files[name] = f
        end
        return f
    end

    local function persist(name, f)
        if opts.writeFile then opts.writeFile(name, buffer.readstring(f.buf, 0, f.size)) end
    end

    local function ensure(f, size)
        local cap = buffer.len(f.buf)
        if size <= cap then return end
        local newCap = math.max(size, cap * 2, 4096)
        local nb = buffer.create(newCap)
        buffer.copy(nb, 0, f.buf, 0, f.size)
        f.buf = nb
    end

    local wasi = {}
    function wasi.fd_prestat_get(fd, ptr)
        if fd ~= 3 then return ERRNO.badf end
        buffer.writeu8(mem.data, ptr, 0)
        setU32(ptr + 4, 1)
        return 0
    end
    function wasi.fd_prestat_dir_name(fd, ptr, len)
        if fd ~= 3 then return ERRNO.badf end
        buffer.writeu8(mem.data, ptr, 47) -- "/"
        return 0
    end
    function wasi.fd_fdstat_get(fd, ptr)
        local kind
        if fd <= 2 then kind = 2 elseif fd == 3 then kind = 3 elseif fds[fd] then kind = 4 else return ERRNO.badf end
        buffer.fill(mem.data, ptr, 0, 24)
        buffer.writeu8(mem.data, ptr, kind)
        for k = 8, 23 do buffer.writeu8(mem.data, ptr + k, 255) end
        return 0
    end
    function wasi.fd_fdstat_set_flags() return 0 end
    function wasi.path_open(dirfd, dirflags, pathPtr, pathLen, oflags, rightsBase, rightsInh, fdflags, outPtr)
        local name = normal(readStr(pathPtr, pathLen))
        local f = getFile(name)
        local creat, trunc = bit32.band(oflags, 1) ~= 0, bit32.band(oflags, 8) ~= 0
        if bit32.band(oflags, 2) ~= 0 then return ERRNO.nosys end -- directories
        if not f then
            if not creat then return ERRNO.noent end
            f = { buf = buffer.create(4096), size = 0 }
            files[name] = f
        elseif trunc then
            f.size = 0
        end
        local fd = nextFd
        nextFd = nextFd + 1
        fds[fd] = { name = name, pos = 0, file = f, dirty = creat or trunc, append = bit32.band(fdflags, 1) ~= 0 }
        setU32(outPtr, fd)
        return 0
    end
    function wasi.fd_read(fd, iovs, count, nreadPtr)
        local h = fds[fd]
        if not h then setU32(nreadPtr, 0); return fd == 0 and 0 or ERRNO.badf end
        local total = 0
        local f = h.file
        for i = 0, count - 1 do
            local ptr, len = u32(iovs + i * 8), u32(iovs + i * 8 + 4)
            local n = math.min(len, f.size - h.pos)
            if n > 0 then
                buffer.copy(mem.data, ptr, f.buf, h.pos, n)
                h.pos = h.pos + n
                total = total + n
            end
            if n < len then break end
        end
        setU32(nreadPtr, total)
        maybeYield()
        return 0
    end
    function wasi.fd_write(fd, iovs, count, nwrittenPtr)
        local total = 0
        if fd == 1 or fd == 2 then
            for i = 0, count - 1 do
                local ptr, len = u32(iovs + i * 8), u32(iovs + i * 8 + 4)
                if len > 0 then logLines[#logLines + 1] = readStr(ptr, len) end
                total = total + len
            end
            if #logLines > 200 then table.remove(logLines, 1) end
            setU32(nwrittenPtr, total)
            return 0
        end
        local h = fds[fd]
        if not h then return ERRNO.badf end
        local f = h.file
        if h.append then h.pos = f.size end
        for i = 0, count - 1 do
            local ptr, len = u32(iovs + i * 8), u32(iovs + i * 8 + 4)
            if len > 0 then
                ensure(f, h.pos + len)
                buffer.copy(f.buf, h.pos, mem.data, ptr, len)
                h.pos = h.pos + len
                if h.pos > f.size then f.size = h.pos end
                total = total + len
            end
        end
        h.dirty = true
        setU32(nwrittenPtr, total)
        return 0
    end
    function wasi.fd_seek(fd, offset, whence, outPtr)
        local h = fds[fd]
        if not h then return ERRNO.badf end
        local off = i64(offset)
        local pos
        if whence == 0 then pos = off elseif whence == 1 then pos = h.pos + off else pos = h.file.size + off end
        if pos < 0 then return ERRNO.inval end
        h.pos = pos
        setU32(outPtr, pos % 4294967296)
        setU32(outPtr + 4, math.floor(pos / 4294967296))
        return 0
    end
    function wasi.fd_close(fd)
        local h = fds[fd]
        if not h then return fd <= 3 and 0 or ERRNO.badf end
        if h.dirty then pcall(persist, h.name, h.file) end
        fds[fd] = nil
        return 0
    end
    function wasi.path_unlink_file(dirfd, pathPtr, pathLen)
        local name = normal(readStr(pathPtr, pathLen))
        if not getFile(name) then return ERRNO.noent end
        files[name] = nil
        if opts.deleteFile then pcall(opts.deleteFile, name) end
        return 0
    end
    function wasi.path_rename(fd1, oldPtr, oldLen, fd2, newPtr, newLen)
        local old, new = normal(readStr(oldPtr, oldLen)), normal(readStr(newPtr, newLen))
        local f = getFile(old)
        if not f then return ERRNO.noent end
        files[new], files[old] = f, nil
        pcall(persist, new, f)
        if opts.deleteFile then pcall(opts.deleteFile, old) end
        return 0
    end
    function wasi.path_create_directory() return 0 end
    function wasi.path_remove_directory() return 0 end
    function wasi.proc_exit(code)
        -- the end of Doom's log says why it stopped (e.g. a lump missing from the WAD)
        local tail = table.concat(logLines):sub(-300):gsub("%s+", " ")
        error("DOOM_EXIT:" .. tostring(code) .. (code ~= 0 and (" " .. tail) or ""), 0)
    end

    local env = {}
    local sound = opts.sound
    local function soundCall(name, ...)
        local fn = sound and sound[name]
        if fn then pcall(fn, ...) end
    end
    function env.host_sfx_start(ptr, channel, vol, sep)
        local name = readStr(ptr, 8):gsub("%z.*", ""):upper()
        soundCall("start", name, channel, vol, sep)
    end
    function env.host_sfx_stop(channel) soundCall("stop", channel) end
    function env.host_sfx_params(channel, vol, sep) soundCall("params", channel, vol, sep) end
    function env.host_music(op, ptr, len, arg)
        if op == 1 then
            if len > 0 and len < 16777216 then soundCall("musicPlay", readStr(ptr, len), arg ~= 0) end
        elseif op == 2 then soundCall("musicStop")
        elseif op == 3 then soundCall("musicPause")
        elseif op == 4 then soundCall("musicResume")
        elseif op == 5 then soundCall("musicVolume", arg)
        end
    end
    function env.host_ticks()
        maybeYield()
        return math.floor(gameMs) % 4294967296
    end
    -- Doom only sleeps while waiting for its next tic: moving the clock on ends the wait
    function env.host_sleep(ms) gameMs = gameMs + ms end
    function env.host_draw(ptr, w, h) screenPtr, screenW, screenH = ptr, w, h end
    function env.host_title(ptr) end
    -- Doom's palette entries are b, g, r, a bytes
    function env.host_palette(ptr)
        local d = mem.data
        for i = 0, 255 do
            local p = ptr + i * 4
            pal[i + 1] = buffer.readu8(d, p + 2) + buffer.readu8(d, p + 1) * 256 + buffer.readu8(d, p) * 65536 + 4278190080
        end
    end

    local function wrap(t)
        local out = {}
        for k, fn in pairs(t) do out[k] = fn end
        return { func_list = out }
    end

    local instantiate = makeWasm()
    local exports = instantiate({ env = wrap(env), wasi_snapshot_preview1 = wrap(wasi) })
    mem = exports.memory_list.memory
    local fn = exports.func_list

    local doom = { log = logLines }
    function doom.start()
        local wadName = identify(opts.wadData) or "doom.wad"
        files[wadName] = fileFromString(opts.wadData)
        starting = true
        lastYield = opts.clock()
        fn._initialize()
        local ptr = fn.puppy_wadname()
        local arg = "/" .. wadName
        buffer.writestring(mem.data, ptr, arg)
        buffer.writeu8(mem.data, ptr + #arg, 0)
        fn.puppy_start()
        starting = false
        return wadName
    end
    function doom.tick() fn.puppy_tick() end
    function doom.advance(ms) gameMs = gameMs + ms end
    function doom.blit(out)
        if not screenPtr then return false end
        local d, src = mem.data, screenPtr
        local readu8, writeu32, p = buffer.readu8, buffer.writeu32, pal
        for i = 0, screenW * screenH - 1 do
            writeu32(out, i * 4, p[readu8(d, src + i) + 1])
        end
        return true
    end
    function doom.key(pressed, code) fn.puppy_key(pressed and 1 or 0, code) end
    function doom.mouse(buttons, dx, dy) fn.puppy_mouse(buttons, dx, dy) end
    function doom.lastLog() return table.concat(logLines) end
    return doom
end

return Doom

end)()
Doom.makeWasm = makeWasm
return Doom
